// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 initialContractBalance) public {
        initialContractBalance = bound(initialContractBalance, 1, 100 ether);

        vm.deal(address(c), initialContractBalance);

        address owner = address(uint160(uint256(keccak256(abi.encodePacked("owner")))));
        owner = address(this);
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        c.sudicideAnyone();

        assertEq(owner.balance, ownerBalanceBefore + initialContractBalance, "Owner did not receive the funds");
    }
}
